- name: Post triage starting
  if: ${{ env.SLACK_BOT_TOKEN != '' && steps.set.outputs.slack_channel != '' && steps.set.outputs.slack_thread_ts != '' }}
  env:
    SLACK_CHANNEL: ${{ steps.set.outputs.slack_channel }}
    SLACK_THREAD_TS: ${{ steps.set.outputs.slack_thread_ts }}
    TRIAGE_RUN_URL: https://github.com/${{ github.repository }}/actions/runs/${{ github.run_id }}
  shell: bash
  run: |
    scripts/post-slack-message.sh ":hourglass_flowing_sand: E2E triage started — <${TRIAGE_RUN_URL}|view triage run>"

- name: Post triage result
  if: ${{ always() && (steps.triage.outputs.outcome == 'success' || steps.triage.outputs.outcome == 'failure') && env.SLACK_BOT_TOKEN != '' && env.SLACK_CHANNEL != '' && env.SLACK_THREAD_TS != '' }}
  shell: bash
  env:
    TRIAGE_OUTCOME: ${{ steps.triage.outputs.outcome }}
    TRIAGE_OUTPUT_OUTCOME: ${{ steps.triage_output.outcome }}
    TRIAGE_RUN_ID: ${{ github.run_id }}
    SUMMARY_URL: https://github.com/${{ github.repository }}/actions/runs/${{ github.run_id }}
  run: |
    set -euo pipefail

    if [ "$TRIAGE_OUTCOME" != "success" ]; then
      scripts/post-slack-message.sh ":x: E2E triage failed — <${SUMMARY_URL}|view run>"
      exit 0
    fi

    if [ "$TRIAGE_OUTPUT_OUTCOME" != "success" ]; then
      scripts/post-slack-message.sh ":warning: E2E triage completed but output extraction failed — <${SUMMARY_URL}|view run>"
      exit 0
    fi

    # Construct Fix It URL
    encoded_run_url="$(python3 -c "import urllib.parse, os; print(urllib.parse.quote(os.environ['RUN_URL'], safe=''))")"
    encoded_agents="$(python3 -c "import urllib.parse, os; print(urllib.parse.quote(os.environ['FAILED_AGENTS'], safe=''))")"
    fix_url="https://e2e-triage.entireio.workers.dev/fix?triage_run_id=${TRIAGE_RUN_ID}&run_url=${encoded_run_url}&failed_agents=${encoded_agents}&slack_channel=${SLACK_CHANNEL}&slack_thread_ts=${SLACK_THREAD_TS}"

    # Block Kit payload with button
    payload="$(jq -n \
      --arg summary_url "$SUMMARY_URL" \
      --arg fix_url "$fix_url" \
      '{
        text: "E2E triage complete",
        blocks: [
          {
            type: "section",
            text: {
              type: "mrkdwn",
              text: (":white_check_mark: E2E triage complete — <" + $summary_url + "|view results>")
            }
          },
          {
            type: "actions",
            elements: [
              {
                type: "button",
                text: { type: "plain_text", text: "Fix It" },
                url: $fix_url,
                style: "primary"
              }
            ]
          }
        ]
      }')"

    scripts/post-slack-message.sh --payload "$payload"

